"""`dev dashboard`: the project command centre.

One self-contained HTML file (inline CSS, JS and SVG; data embedded as JSON)
rendered from the registry that `dev sync` produces, the PR cache, the canary
and guard logs, and the handoff repository's Markdown (Explorer).

It is organised around jobs, not counts, with drill-down pages:
  Home         a compact summary of everything: KPIs, the top of the action list,
               initiative cards, who is working on what, what changed
  Initiatives  list (cards or table, roadmap) -> #/initiatives/<slug>: overview,
               member projects (grouped, searchable), tasks, plans, sessions, docs
  Projects     dense table -> #/projects/<id>: overview, tasks, PRs, worktrees,
               plans, sessions, the handoff note
  Team         one card per person (user@host): live sessions, locks, claimed
               tasks, recent sessions; collisions flagged
  Tasks        work items across scopes (kanban or list) -> the task drawer with
               lock state, the full changelog and the `dev task` commands
  Activity · Explorer · Health   as before

Decisions (action priority, project health, "since yesterday", guard rule
grouping) are computed here in Python so they are unit-tested; the page only
renders them. Every string from notes, files and git is inserted with DOM text
APIs (never innerHTML); the embedded JSON escapes <, > and &.

Brand: Firefly Software (fireflysoftwaresolutions/brand-kit). The Firefly logo
is the official SVG from lib/devkit/art (generated by the brand-kit; never
redrawn), shown in the paper or charcoal colourway by theme.
"""
from __future__ import annotations

import calendar
import json
import os
import re
import socket
import subprocess
import time
from pathlib import Path

from . import core

EXPLORER_CAP = 2_000_000          # bytes of Markdown embedded for the Explorer (newest files first)
ROOT_FILES = ("PROJECTS.md", "TASKS.md", "ACTIVITY.md", "README.md")
WORKTREE_KEYS = ("path", "branch", "location", "active", "locked", "modified", "untracked", "unpushed", "pr",
                 "last_activity", "size_kb", "missing", "ahead", "behind")
ART = Path(__file__).resolve().parent / "art"
IDLE_WORK_S = 2 * 86400

GUARD_RULES = [
    ("branch", "Branch naming", r"^Branch `"),
    ("worktree", "Unmanaged worktree", r"worktree add|unmanaged worktree|is a git worktree"),
    ("clone", "Clone outside the layout", r"Clone to the canonical|Clone repos with|Clone non-GitHub"),
    ("layout", "Workspace layout", r"Workspace layout|not a GitHub owner folder|Files do not go directly|Sibling copies"),
    ("outside", "Write outside the workspace", r"Writes outside"),
    ("backup", "Backup copy", r"backup cop"),
    ("push-budget", "CI push budget", r"push #\d+ of"),
    ("force-push", "Force push", r"orce-push|force push"),
    ("rerun", "Blind CI re-run", r"Re-running CI"),
    ("attribution", "AI attribution", r"AI attribution"),
    ("delete", "Destructive delete", r"Refusing to|repository checkout|would wipe"),
    ("reset", "Hard reset with changes", r"reset --hard"),
    ("clean", "git clean -x", r"git clean"),
]


# --------------------------------------------------------------------------- helpers

def safe_json(obj) -> str:
    """JSON that is safe inside <script type="application/json">: no raw <, > or & anywhere."""
    s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"), default=str)
    return (s.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
             .replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))


def _session_ts(line: str) -> int:
    m = re.match(r"^(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2})", line or "")
    if not m:
        return 0
    try:
        return int(time.mktime(time.strptime(f"{m.group(1)} {m.group(2)}:{m.group(3)}", "%Y-%m-%d %H:%M")))
    except (ValueError, OverflowError):
        return 0


def _iso_ts(s) -> int:
    try:
        return int(calendar.timegm(time.strptime(str(s)[:19], "%Y-%m-%dT%H:%M:%S")))
    except (ValueError, TypeError):
        return 0


def _midnight(now: float, days_back: int = 0) -> int:
    t = time.localtime(now - days_back * 86400)
    return int(time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 0, 0, 0, 0, 0, -1)))


def _mine(pr: dict, me: str) -> bool:
    author = (pr.get("author") or "").lower()
    return not me or not author or author == me.lower()


def _open_tasks(ns: dict) -> list:
    t = (ns or {}).get("tasks") or {}
    return list(t.get("now") or []) + list(t.get("next") or []) + list(t.get("later") or [])


def task_index(ns: dict, text: str):
    """1-based index of an open task as `dev task` numbers them (Now, Next, Later order)."""
    open_ = _open_tasks(ns)
    return open_.index(text) + 1 if text in open_ else None


def _idle(ts, now) -> float:
    return now - (ts or now)


def explorer_files(handoff: Path, cap: int = EXPLORER_CAP):
    """Markdown files of the handoff repo, root files first then newest first, until `cap` bytes."""
    root = Path(handoff)
    cands = set()
    for name in ROOT_FILES:
        if (root / name).is_file():
            cands.add(root / name)
    for sub in ("initiatives", "projects", "plans", "log"):
        d = root / sub
        if d.is_dir():
            cands.update(p for p in d.rglob("*.md") if p.is_file())

    def mtime(p):
        try:
            return p.stat().st_mtime
        except OSError:
            return 0

    files, total, omitted = [], 0, 0
    for f in sorted(cands, key=lambda p: (p.name not in ROOT_FILES or p.parent != root, -mtime(p))):
        try:
            text = f.read_text(errors="replace")
        except OSError:
            continue
        size = len(text.encode("utf-8", "replace"))
        if total + size > cap:
            omitted += 1
            continue
        total += size
        files.append({"path": str(f.relative_to(root)), "mtime": int(mtime(f)), "size": size, "text": text})
    return files, {"capped": omitted > 0, "omitted": omitted, "bytes": total, "cap": cap}


def pr_cache() -> dict:
    """{owner/repo: [pr]} from devkit's PR cache (~/.local/state/devkit/prs/*.json), all states."""
    out = {}
    d = core.STATE / "prs"
    try:
        for f in d.glob("*.json"):
            try:
                out[f.stem.replace("__", "/", 1)] = json.loads(f.read_text()) or []
            except (OSError, ValueError):
                continue
    except OSError:
        pass
    return out


def merged_prs(cache: dict, since_ts: float) -> list:
    out = []
    for repo, prs in cache.items():
        for pr in prs or []:
            ts = _iso_ts(pr.get("updatedAt") or pr.get("updated"))
            if pr.get("state") == "MERGED" and ts >= since_ts:
                out.append({"repo": repo, "number": pr.get("number"), "title": pr.get("title") or "",
                            "url": pr.get("url") or "", "ts": ts, "author": pr.get("author") or ""})
    return sorted(out, key=lambda x: -x["ts"])


# --------------------------------------------------------------------------- guard

def guard_events(limit: int = 400) -> list:
    """Recent guard decisions from ~/.local/state/devkit/logs/hooks.log."""
    f = core.STATE / "logs" / "hooks.log"
    out = []
    try:
        lines = f.read_text(errors="replace").splitlines()[-6000:]
    except OSError:
        return out
    for ln in lines:
        m = re.match(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}) guard (\w+) (\w+): (.*)$", ln)
        if m:
            out.append({"ts": m.group(1), "agent": m.group(2), "decision": m.group(3), "reason": m.group(4)})
    return out[-limit:]


def guard_rules(events: list) -> list:
    """Group guard decisions by rule: a repeated denial is a signal (an agent fighting the rules)."""
    groups = {}
    for e in events:
        key, label = "other", "Other"
        for k, lab, rx in GUARD_RULES:
            if re.search(rx, e.get("reason", "")):
                key, label = k, lab
                break
        g = groups.setdefault(key, {"rule": key, "label": label, "count": 0, "deny": 0, "ask": 0, "agents": {},
                                    "last": "", "example": ""})
        g["count"] += 1
        g[e.get("decision") if e.get("decision") in ("deny", "ask") else "deny"] += 1
        g["agents"][e.get("agent", "?")] = g["agents"].get(e.get("agent", "?"), 0) + 1
        if e.get("ts", "") >= g["last"]:
            g["last"], g["example"] = e.get("ts", ""), e.get("reason", "")
    return sorted(groups.values(), key=lambda g: (-g["count"], g["label"]))


# --------------------------------------------------------------------------- health & actions

def project_health(p: dict, now: float = None) -> dict:
    """{level: ok|warn|risk, reasons: [...]} from PRs, note status, tasks and git state."""
    now = now or time.time()
    risk, warn = [], []
    for pr in p.get("prs_open") or []:
        n = pr.get("number")
        if pr.get("checks") == "failing":
            risk.append(f"PR #{n} is failing CI")
        if pr.get("review") == "CHANGES_REQUESTED":
            risk.append(f"PR #{n} has changes requested")
        if pr.get("mergeable") == "CONFLICTING":
            warn.append(f"PR #{n} has merge conflicts")
    ns = p.get("note_summary") or {}
    if ns.get("status") == "blocked":
        risk.append("marked blocked in the handoff note")
    for t in ((ns.get("tasks") or {}).get("overdue") or []):
        risk.append("overdue task: " + re.sub(r"\s*\bdue:\S+", "", t)[:60])
    m = p.get("main") or {}
    dirty = (m.get("modified") or 0) + (m.get("untracked") or 0)
    if dirty and not m.get("active") and _idle(m.get("last_activity"), now) > IDLE_WORK_S:
        warn.append(f"{dirty} uncommitted change(s), idle {int(_idle(m.get('last_activity'), now) // 86400)}d")
    if m.get("unpushed") and not m.get("active") and _idle(m.get("last_activity"), now) > 86400:
        warn.append(f"{m['unpushed']} commit(s) not pushed")
    for w in p.get("worktrees") or []:
        wd = (w.get("modified") or 0) + (w.get("untracked") or 0)
        if (wd or w.get("unpushed")) and not w.get("active") and _idle(w.get("last_activity"), now) > IDLE_WORK_S:
            warn.append(f"worktree {w.get('branch')} has unsaved work, idle")
    if p.get("canonical_ok") is False and p.get("local", True) is not False:
        warn.append("not at its canonical path")
    if ns.get("due") and ns["due"] < time.strftime("%Y-%m-%d", time.localtime(now)) and ns.get("status") not in ("done", "archived"):
        risk.append(f"past its due date ({ns['due']})")
    level = "risk" if risk else "warn" if warn else "ok"
    return {"level": level, "reasons": risk + warn}


def _task_flag(scope: str) -> str:
    return f"-i {scope[len('initiatives/'):]}" if scope.startswith("initiatives/") else f"-p {scope}"


def build_actions(reg: dict, now: float = None, items: list = None, colls: list = None) -> list:
    """The prioritised 'what needs me now' list. Each item carries the one command that moves it forward."""
    now = now or time.time()
    me = reg.get("github_user") or ""
    acts = []
    items = items or []
    by_title = {}
    for it in items:
        by_title.setdefault((it["scope"], it["title"]), it)

    def add(rank, sev, kind, project, title, detail, cmd, url=None, ts=0):
        acts.append({"rank": rank, "sev": sev, "kind": kind, "project": project, "title": title, "detail": detail,
                     "cmd": cmd, "url": url, "ts": int(ts or 0)})

    reclaim = []
    for p in reg.get("projects") or []:
        pid, repo = p.get("id"), p.get("github") or p.get("id")
        wts = {w.get("branch"): w for w in p.get("worktrees") or []}
        default = p.get("default_branch") or "main"
        for pr in p.get("prs_open") or []:
            n, ts, mine = pr.get("number"), _iso_ts(pr.get("updated")), _mine(pr, me)
            title = pr.get("title") or ""
            if mine and pr.get("checks") == "failing":
                add(10, "risk", "ci-failing", pid, f"PR #{n} is failing CI", title,
                    f"gh pr checks {n} -R {repo} --watch", pr.get("url"), ts)
            if mine and pr.get("review") == "CHANGES_REQUESTED":
                add(20, "risk", "changes-requested", pid, f"PR #{n}: changes requested", title,
                    f"gh pr view {n} -R {repo} --comments", pr.get("url"), ts)
            if mine and pr.get("mergeable") == "CONFLICTING":
                w = wts.get(pr.get("branch"))
                cmd = (f"cd {w['path']} && git fetch origin && git rebase origin/{default}" if w and w.get("path")
                       else f"dcd {pid} && gh pr checkout {n} && git rebase origin/{default}")
                add(22, "warn", "conflicts", pid, f"PR #{n} has merge conflicts", title, cmd, pr.get("url"), ts)
            if pr.get("review") == "REVIEW_REQUIRED" and pr.get("checks") != "failing" and not pr.get("draft"):
                if mine:
                    add(30, "warn", "review-waiting", pid, f"PR #{n} is waiting for review", title,
                        f"gh pr view {n} -R {repo} --web", pr.get("url"), ts)
                else:
                    add(32, "warn", "review-requested", pid, f"Review PR #{n} by @{pr.get('author')}", title,
                        f"gh pr diff {n} -R {repo}", pr.get("url"), ts)
        ns = p.get("note_summary") or {}
        if ns.get("status") == "blocked":
            state = [re.sub(r"^\s*([-*+]|\d+\.)\s*(\[[ xX~]\]\s*)?", "", ln).strip()
                     for ln in (ns.get("state") or "").splitlines() if ln.strip()]
            add(40, "risk", "blocked", pid, f"{p.get('name') or pid} is blocked", state[0][:160] if state else "",
                f"dev handoff {pid}", None, p.get("last_activity"))
        for t in (ns.get("tasks") or {}).get("overdue") or []:
            it = by_title.get((pid, t))
            due = re.search(r"\bdue:(\d{4}-\d{2}-\d{2})", t)
            k = task_index(ns, t)
            cmd = (f"dev task -p {pid} done {it['id']}" if it else f"dev task -p {pid} done {k}" if k else f"dev handoff {pid}")
            add(50, "risk", "overdue", pid, "Overdue task" + (f" (due {(it or {}).get('due') or due.group(1)})" if (it and it.get("due")) or due else ""),
                re.sub(r"\s*\bdue:\S+", "", t), cmd)
        m = p.get("main") or {}
        checkouts = [(p.get("path"), m.get("branch"), m)] + [(w.get("path"), w.get("branch"), w)
                                                           for w in p.get("worktrees") or [] if not w.get("missing")]
        for path, branch, co in checkouts:
            if co.get("active"):
                continue
            dirty = (co.get("modified") or 0) + (co.get("untracked") or 0)
            idle = _idle(co.get("last_activity"), now)
            if dirty and idle > IDLE_WORK_S:
                add(60, "warn", "idle-work", pid, f"{dirty} uncommitted change(s) idle {int(idle // 86400)}d",
                    f"{p.get('name') or pid} · {branch}", f"cd {path} && git status -sb", None, co.get("last_activity"))
            elif co.get("unpushed") and idle > 86400:
                add(62, "warn", "idle-work", pid, f"{co['unpushed']} commit(s) not pushed",
                    f"{p.get('name') or pid} · {branch}", f"cd {path} && git status -sb", None, co.get("last_activity"))
        for w in p.get("worktrees") or []:
            pr = w.get("pr") or {}
            clean = not (w.get("modified") or w.get("untracked") or w.get("unpushed"))
            if pr.get("state") in ("MERGED", "CLOSED") and not w.get("active") and clean and not w.get("missing"):
                reclaim.append((pid, w.get("branch"), pr.get("number"), pr.get("state"), w.get("size_kb") or 0))
        if p.get("canonical_ok") is False and p.get("path") and p.get("local", True) is not False:
            add(80, "info", "layout", pid, f"{p.get('name') or pid} is outside the workspace layout",
                f"canonical path: {core.tilde(p.get('canonical') or '')}", f"dev adopt {core.tilde(p['path'])}")
        if ns:
            last = max([_session_ts(s) for s in ns.get("sessions") or []] or [0])
            recent = sum(v for k, v in (p.get("activity") or {}).items()
                         if k >= time.strftime("%Y-%m-%d", time.localtime(now - 7 * 86400)))
            if recent and (p.get("last_activity") or 0) - last > 3 * 86400:
                add(85, "info", "stale-note", pid, "Handoff note is behind the code",
                    f"{recent} commit(s) this week, " + ("no session logged yet" if not last else
                                                         "last session " + time.strftime("%b %d", time.localtime(last))),
                    f"dev handoff {pid}")
    if len(reclaim) == 1:
        pid, br, n, st, kb = reclaim[0]
        add(70, "info", "reclaim", pid, f"Worktree {br} is done (PR #{n} {st.lower()})", f"{kb // 1024} MB to reclaim",
            f"dev wt rm {br}")
    elif reclaim:
        add(70, "info", "reclaim", None, f"{len(reclaim)} finished worktrees to reclaim",
            ", ".join(f"{br} (#{n})" for _, br, n, _, _ in reclaim[:5]) +
            f" · {sum(r[4] for r in reclaim) // 1024} MB", "dev gc --apply")
    today = time.strftime("%Y-%m-%d", time.localtime(now))
    for ini in reg.get("initiatives") or []:
        if not isinstance(ini, dict):
            continue
        slug, title = ini.get("id"), ini.get("title") or ini.get("id")
        if ini.get("status") == "blocked":
            state = [re.sub(r"^\s*([-*+]|\d+\.)\s*(\[[ xX~]\]\s*)?", "", ln).strip()
                     for ln in (ini.get("state") or ini.get("risks") or "").splitlines() if ln.strip()]
            add(41, "risk", "blocked", None, f"Initiative {title} is blocked", state[0][:160] if state else "",
                f"dev initiative show {slug}", None, ini.get("last_activity"))
        if ini.get("due") and ini["due"] < today and ini.get("status") not in ("done", "archived"):
            add(45, "risk", "overdue", None, f"Initiative {title} is past its due date ({ini['due']})",
                (f"{ini.get('progress')}% done" if ini.get("progress") is not None else "") +
                (f" · milestone {ini['milestone']}" if ini.get("milestone") else ""), f"dev initiative show {slug}")
        for t in ((ini.get("tasks") or {}).get("overdue") or []):
            it = by_title.get((f"initiatives/{slug}", t))
            k = task_index({"tasks": ini.get("tasks")}, t)
            due = re.search(r"\bdue:(\d{4}-\d{2}-\d{2})", t)
            cmd = (f"dev task -i {slug} done {it['id']}" if it else f"dev task -i {slug} done {k}" if k else f"dev initiative show {slug}")
            add(50, "risk", "overdue", None, f"Overdue in {title}" + (f" (due {due.group(1)})" if due else ""),
                re.sub(r"\s*\bdue:\S+", "", t), cmd)
    for c in colls or []:
        if c["kind"] == "same-branch":
            add(36, "warn", "collision", c["project"], f"Two sessions on {c['project'].split('/')[-1]}@{c['branch'] or '?'}",
                ", ".join(c["who"]), "dev team")
        elif c["kind"] == "expired-lock":
            add(35, "warn", "expired-lock", c["scope"] if not c["scope"].startswith("initiatives/") else None,
                f"Expired lock still held on {c['id']}", c["text"],
                f"dev task {_task_flag(c['scope'])} release {c['id']} --why \"lock expired\"")
    for it in items:
        if it.get("status") == "blocked" and me and _who(it.get("claimed_by")).split("@")[0] == me.lower():
            add(42, "risk", "blocked-task", it["scope"] if not it["scope"].startswith("initiatives/") else None,
                f"Your task {it['id']} is blocked", it["title"], f"dev task {_task_flag(it['scope'])} show {it['id']}")
    drift = reg.get("drift")
    if drift:
        add(90, "warn", "drift", None, f"Agent configuration drifted ({len(drift)} setting(s))",
            "Claude Code or Codex no longer match the devkit configuration", "dev config diff")
    for key, prov in ((reg.get("providers") or {}).items()):
        if isinstance(prov, dict) and prov.get("installed") and prov.get("logged_in") is False:
            add(95, "warn", "sign-in", None, f"{prov.get('name') or key} is not signed in", "",
                "claude" if key == "claude" else "codex login")
    acts.sort(key=lambda a: (a["rank"], -a["ts"]))
    return acts


def since_yesterday(reg: dict, cache: dict, now: float = None, items: list = None, slog: list = None, me: str = "") -> dict:
    """What happened since the start of yesterday: sessions, commits, merged PRs, completed tasks.

    This machine's live sessions (reg["sessions"]) are `me`'s; a logged line of the same session is not repeated."""
    from . import work
    now = now or time.time()
    me = me or f"{reg.get('github_user') or os.environ.get('USER', '')}@{socket.gethostname().split('.')[0].lower()}"
    y0 = _midnight(now, 1)
    yday = time.strftime("%Y-%m-%d", time.localtime(y0))
    sessions = []
    for s in reg.get("sessions") or []:
        ts = s.get("last_seen") or s.get("started") or 0
        if ts >= y0:
            sessions.append({"ts": ts, "project": s.get("project"), "agent": s.get("agent"),
                             "branch": s.get("branch"), "text": s.get("status") or "", "live": bool(s.get("active")), "who": me,
                             "pre": "", "parts": status_parts(s.get("status"))})
    seen = {(x["project"], x["agent"]) for x in sessions}
    logged = {ln["scope"] for ln in slog or []}
    live_ts = {}
    for x in sessions:
        live_ts[(x["project"], x["agent"])] = max(live_ts.get((x["project"], x["agent"]), 0), x["ts"])
    for ln in slog or []:
        dup = ln["who"] in ("", me) and (ln["scope"], ln["agent"]) in seen and ln["ts"] <= live_ts[(ln["scope"], ln["agent"])]
        if ln["ts"] >= y0 and not dup:
            sessions.append({"ts": ln["ts"], "project": ln["scope"], "agent": ln["agent"], "branch": ln["branch"],
                             "text": ln["text"], "live": False, "who": ln["who"],
                             "pre": ln.get("pre", ""), "parts": ln.get("parts")})
    for p in reg.get("projects") or []:
        if p.get("id") in logged:
            continue
        for line in ((p.get("note_summary") or {}).get("sessions") or []):
            ts = _session_ts(line)
            if ts >= y0:
                body = re.sub(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}\s*·\s*", "", line)
                agent = body.split(" · ", 1)[0]
                if (p.get("id"), agent) in seen and ts < max([x["ts"] for x in sessions if x["project"] == p.get("id")] or [0]):
                    continue
                sessions.append({"ts": ts, "project": p.get("id"), "agent": agent, "branch": "",
                                 "text": body.split(" · ", 1)[1] if " · " in body else body, "live": False, "who": ""})
    commits = []
    for p in reg.get("projects") or []:
        n = sum(v for k, v in (p.get("activity") or {}).items() if k >= yday)
        if n:
            commits.append([p.get("id"), n])
    done = [{"project": i["scope"], "text": i["title"], "id": i["id"], "who": _who(i.get("updated_by"))}
            for i in sorted(items or [], key=lambda i: i.get("updated") or "", reverse=True)
            if i["status"] == "done" and work.parse_iso(i.get("updated") or "") >= y0]
    scoped = {i["scope"] for i in items or []}
    for p in reg.get("projects") or []:
        if p.get("id") in scoped:
            continue
        for t in ((p.get("note_summary") or {}).get("tasks") or {}).get("done_recent") or []:
            m = re.search(r"✓\s*(\d{4}-\d{2}-\d{2})", t)
            if m and m.group(1) >= yday:
                done.append({"project": p.get("id"), "text": re.sub(r"\s*✓\s*\d{4}-\d{2}-\d{2}", "", t)})
    return {"from": y0, "sessions": sorted(sessions, key=lambda x: -x["ts"])[:40],
            "commits": sorted(commits, key=lambda x: -x[1]), "merged": merged_prs(cache, y0)[:20], "done": done[:30]}


# --------------------------------------------------------------------------- work items, presence, sessions, plans

MARKER_RE = re.compile(r"^[\W_]*(?:\[\s*firefly\s*>\s*devkit\s*\]|devkit(?=[\s·:—*`]))[\s·:—*`]*", re.I)
CHECK_GLYPHS = "✓⚠✗–"


def status_parts(line: str):
    """A saved status line -> {project, branch, task, done, check, progress, next}; None for the legacy one-line form.

    Current: `<project> · <branch> ❯ <task> ❯ <done> ❯ <✓ check> [❯ ▸ <progress>] ❯ next → <next>`; the older
    segmented form (`api ⎇ main ❯ T-… ❯ … ❯ next → …`) parses the same way. Split on ❯: the first segment is project
    and branch, the second the task (hidden when "-"); ✓/⚠/✗/– is Check, ▸ Progress, "next →" Next, the rest Done."""
    s = MARKER_RE.sub("", str(line or ""), count=1).strip()
    if "❯" not in s:
        return None
    segs = [x.strip() for x in s.split("❯") if x.strip()]
    if len(segs) < 2:
        return None
    out = {"project": segs[0].strip("` "), "branch": "", "task": "" if segs[1] == "-" else segs[1], "done": "", "check": "",
           "progress": "", "next": ""}
    m = re.match(r"^(.*?)\s*(?:·|⎇)\s*(.+)$", segs[0])
    if m:
        out["project"], out["branch"] = m.group(1).strip("` "), m.group(2).strip("` ")
    done = []
    for x in segs[2:]:
        if x[:1] in CHECK_GLYPHS and not out["check"]:
            out["check"] = x
        elif x[:1] == "▸":
            out["progress"] = x[1:].strip()
        elif re.match(r"(?i)^next\s*(→|->|:)", x):
            out["next"] = re.sub(r"(?i)^next\s*(→|->|:)\s*", "", x)
        else:
            done.append(x)
    out["done"] = " · ".join(done)
    return out


def _with_status(s: dict, key: str = "status") -> dict:
    return dict(s, status_parts=status_parts(s.get(key))) if isinstance(s, dict) else s


def _log_status(text: str):
    """Session-log text '… · status: <saved line>' -> (text before the status, parts) when the status parses."""
    i = (text or "").rfind("status: ")
    if i < 0:
        return "", None
    parts = status_parts(text[i + len("status: "):])
    return (text[:i].rstrip(" ·"), parts) if parts else ("", None)


def _who(s: str) -> str:
    """'user@host (agent:session)' -> 'user@host'."""
    return (s or "").split(" ")[0].strip()


def read_items(handoff: Path, now: float = None) -> list:
    """Every work item under <handoff>/items (all scopes), with lock state and changelog."""
    from . import work
    now = now or time.time()
    base = Path(handoff) / "items"
    out = []
    if not base.is_dir():
        return out
    for f in sorted(base.rglob("*.md")):
        try:
            it = work.parse(f.read_text(errors="replace"))
        except (OSError, ValueError):
            continue
        m = it.get("meta") or {}
        scope = m.get("scope") or str(f.parent.relative_to(base))
        holder = m.get("claimed_by") or ""
        expired = bool(holder) and work.parse_iso(m.get("lock_expires") or "") < now
        links = m.get("links") or []
        if isinstance(links, str):
            links = [x.strip() for x in links.strip("[]").split(",") if x.strip()]
        out.append({"id": m.get("id") or f.stem, "type": m.get("type") or "task", "title": m.get("title") or it.get("title") or f.stem,
                    "scope": scope, "initiative": scope[len("initiatives/"):] if scope.startswith("initiatives/") else "",
                    "status": m.get("status") or "todo", "bucket": m.get("bucket") or "next", "priority": m.get("priority") or "normal",
                    "assignee": m.get("assignee") or "", "claimed_by": holder, "claimed_at": m.get("claimed_at") or "",
                    "lock_expires": m.get("lock_expires") or "", "lock": ("expired" if expired else "held") if holder else "",
                    "due": m.get("due") or "", "links": links, "version": m.get("version") or 1,
                    "created": m.get("created") or "", "created_by": m.get("created_by") or "",
                    "updated": m.get("updated") or "", "updated_by": m.get("updated_by") or "",
                    "body": (it.get("body") or "")[:4000], "changelog": (it.get("changelog") or [])[:60],
                    "path": str(f.relative_to(Path(handoff)))})
    return out


def read_presence(handoff: Path, reg: dict, max_age_h: float = 24, now: float = None) -> list:
    """Team presence (reg["team"] when the registry carries it, else <handoff>/presence/*.json)."""
    from . import work
    now = now or time.time()
    if reg.get("team") is not None:
        return [t for t in reg.get("team") or [] if isinstance(t, dict)]
    out = []
    d = Path(handoff) / "presence"
    for f in sorted(d.glob("*.json")) if d.is_dir() else []:
        try:
            p = json.loads(f.read_text())
        except (OSError, ValueError):
            continue
        if now - work.parse_iso(p.get("updated") or "") < max_age_h * 3600:
            out.append(p)
    return out


SESSION_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s*·\s*(.*)$")


def read_session_log(handoff: Path, months: int = 2, limit: int = 1500) -> list:
    """Append-only session logs (<handoff>/sessions/<scope>/<YYYY-MM>.md), newest first."""
    base = Path(handoff) / "sessions"
    out = []
    if not base.is_dir():
        return out
    by_scope = {}
    for f in base.rglob("*.md"):
        by_scope.setdefault(str(f.parent.relative_to(base)), []).append(f)
    for scope, files in by_scope.items():
        for f in sorted(files, reverse=True)[:months]:
            try:
                lines = f.read_text(errors="replace").splitlines()
            except OSError:
                continue
            for ln in lines:
                if not ln.startswith("- "):
                    continue
                m = SESSION_RE.match(re.sub(r"\s*<!--.*?-->\s*$", "", ln[2:]).strip())
                if not m:
                    continue
                parts = [x.strip() for x in m.group(2).split(" · ")]
                who = parts.pop(0) if parts and "@" in parts[0] and " " not in parts[0] else ""
                agent = parts.pop(0) if parts and parts[0] in ("claude", "codex", "human", "devkit") else ""
                branch = parts.pop(0).strip("`") if parts and parts[0].startswith("`") else ""
                pre, sparts = _log_status(" · ".join(parts))
                out.append({"ts": _session_ts(m.group(1)), "scope": scope, "who": who, "agent": agent, "branch": branch, "pre": pre, "parts": sparts,
                            "text": " · ".join(parts)})
    out.sort(key=lambda x: -x["ts"])
    return out[:limit]


def read_plans(handoff: Path) -> list:
    """Versioned plans and specs (<handoff>/plans/<scope>/*.md)."""
    from . import plans as plansmod
    base = Path(handoff) / "plans"
    out = []
    for f in sorted(base.rglob("*.md")) if base.is_dir() else []:
        try:
            meta, body, log = plansmod._split(f.read_text(errors="replace"))
        except OSError:
            continue
        title = meta.get("title") or next((ln[2:].strip() for ln in body.splitlines() if ln.startswith("# ")), f.stem)
        out.append({"scope": meta.get("scope") or str(f.parent.relative_to(base)), "id": meta.get("id") or "", "title": title,
                    "status": meta.get("status") or "unversioned", "version": meta.get("version") or "",
                    "updated": meta.get("updated") or "", "updated_by": meta.get("updated_by") or "",
                    "needs_revision": plansmod.needs_revision(f), "changelog": log[:20],
                    "path": str(f.relative_to(Path(handoff))), "mtime": int(f.stat().st_mtime)})
    return out


SESSION_KEYS = ("agent", "project", "branch", "started", "status", "last_seen", "session", "progress", "subagents",
                "turn_started")


def live_sessions_of(person: dict, now: float, max_idle_s: float = 2 * 3600) -> list:
    out = []
    for s in person.get("sessions") or []:
        if not isinstance(s, dict):
            continue
        seen = s.get("last_seen") or s.get("started") or 0
        if not seen or now - seen <= max_idle_s:
            out.append(s)
    return out


def collisions(team: list, items: list, now: float = None) -> list:
    """Two people or sessions on the same project and branch; locks that expired but are still held."""
    now = now or time.time()
    by = {}
    for person in team:
        who = person.get("who") or f"{person.get('user')}@{person.get('host')}"
        for s in live_sessions_of(person, now):
            if s.get("project") and s.get("branch"):
                by.setdefault((s["project"], s.get("branch") or ""), []).append((who, s.get("agent") or "agent"))
    out = []
    for (proj, br), lst in sorted(by.items()):
        if len(set(lst)) > 1:
            out.append({"kind": "same-branch", "project": proj, "branch": br, "who": sorted({f"{w} ({a})" for w, a in lst}),
                        "text": f"{len(set(lst))} sessions on {proj}@{br or '?'}: " + ", ".join(sorted({f'{w} ({a})' for w, a in lst}))})
    for it in items:
        if it.get("lock") == "expired" and it.get("status") not in ("done", "cancelled"):
            out.append({"kind": "expired-lock", "id": it["id"], "scope": it["scope"], "holder": it["claimed_by"],
                        "until": it["lock_expires"],
                        "text": f"{it['id']} “{it['title'][:60]}” is still claimed by {_who(it['claimed_by'])}, "
                                f"lock expired {it['lock_expires'][:16].replace('T', ' ')}"})
    return out


def people(team: list, items: list, slog: list, now: float = None, local: list = None, me: str = "") -> list:
    """One entry per person (user@host): presence, live sessions, held locks, claimed items, recent sessions.

    This machine's own sessions come from the local registry (fresher than its presence file)."""
    now = now or time.time()
    out = {}

    def get(who):
        user, _, host = who.partition("@")
        return out.setdefault(who, {"who": who, "user": user, "host": host, "updated": 0, "sessions": [], "locks": [],
                                    "claimed": [], "recent": []})
    from . import work
    for person in team:
        who = f"{person.get('user')}@{person.get('host')}"
        e = get(who)
        e["updated"] = int(work.parse_iso(person.get("updated") or ""))
        e["sessions"] = live_sessions_of(person, now)
        e["locks"] = [lk for lk in person.get("locks") or [] if isinstance(lk, dict)]
    mine = [s for s in local or [] if isinstance(s, dict) and s.get("active")]
    if me and (mine or me in out):
        e = get(me)
        if mine:
            e["sessions"] = [{k: s.get(k) for k in SESSION_KEYS} for s in mine]
            e["updated"] = max(e["updated"], max(int(s.get("last_seen") or 0) for s in mine))
    for it in items:
        if it.get("claimed_by") and it.get("status") not in ("done", "cancelled"):
            get(_who(it["claimed_by"]))["claimed"].append(it["id"])
    for ln in slog:
        if ln.get("who") and ln["who"] in out and len(out[ln["who"]]["recent"]) < 8:
            out[ln["who"]]["recent"].append(ln)
    for ln in slog:
        if ln.get("who") and ln["who"] not in out:
            e = get(ln["who"])
            e["recent"].append(ln)
    return sorted(out.values(), key=lambda e: (-len(e["sessions"]), -len(e["claimed"]), -e["updated"], e["who"]))


def linked_items(items: list, slug: str, members: list) -> list:
    """An initiative's work: its own items plus member-project items that link to it (links: initiative:<slug>)."""
    mem, tag = set(members or []), f"initiative:{slug}"
    return [i for i in items if i["scope"] == f"initiatives/{slug}" or (i["scope"] in mem and tag in i["links"])]


SECRET_RE = re.compile(r"(?i)(bearer\s+|--?(?:token|password|secret|api[_-]?key)[\s=]+|(?:token|password|passwd|secret|"
                       r"authorization|api[_-]?key)[\"']?\s*[=:]\s*(?:bearer\s+)?)[^\s'\"]+"
                       r"|\b(?=[A-Za-z0-9_]*\d)(?=[A-Za-z0-9_]*[A-Za-z])[A-Za-z0-9_]{32,}\b")


def _redact(s: str) -> str:
    """Command lines in timing records may carry credentials: mask them before they reach the page."""
    return SECRET_RE.sub(lambda m: (m.group(1) or "") + "***", str(s or ""))


def _q(vals: list, q: float):
    s = sorted(vals)
    return s[int(q * (len(s) - 1))] if s else None


def timing_summary(recs: list, now: float = None) -> dict:
    """Time predictability from the timing records (progress.records): turn length, estimate accuracy (actual ÷
    estimate of finished runs), the slowest commands and subagent durations; overall and per project."""
    import statistics
    now = now or time.time()

    def st(xs):
        return {"n": len(xs), "median": round(statistics.median(xs), 1) if xs else None,
                "p90": round(_q(xs, 0.9), 1) if xs else None}

    def pick(r):
        out = {k: r.get(k) for k in ("ts", "agent", "project", "secs", "estimate", "steps")}
        out["what"] = _redact(r.get("what"))[:160]
        return out
    month, week = now - 30 * 86400, now - 7 * 86400
    turn = lambda rs: [r["secs"] / 60 for r in rs if r.get("kind") == "turn" and r.get("ts", 0) >= month]  # noqa: E731
    runs = lambda rs: [r for r in rs if r.get("kind") == "run" and (r.get("estimate") or 0) > 0]  # noqa: E731
    ratio = lambda rs: round(statistics.median([r["secs"] / 60 / r["estimate"] for r in runs(rs)]), 2) if runs(rs) else None  # noqa: E731
    tools = sorted((r for r in recs if r.get("kind") == "tool" and r.get("ts", 0) >= week), key=lambda r: -(r.get("secs") or 0))
    subs = [r for r in recs if r.get("kind") == "subagent" and r.get("ts", 0) >= week]
    by = {}
    for r in recs:
        if r.get("project"):
            by.setdefault(r["project"], []).append(r)
    by_project = {}
    for pid, rs in by.items():
        if turn(rs) or runs(rs):
            by_project[pid] = {"turns": st(turn(rs)), "ratio": ratio(rs), "runs": len(runs(rs)),
                               "slow_tools": [pick(r) for r in sorted((r for r in rs if r.get("kind") == "tool" and r.get("ts", 0) >= week),
                                                                       key=lambda r: -(r.get("secs") or 0))[:5]]}
    return {"turns": st(turn(recs)), "ratio": ratio(recs), "runs": len(runs(recs)),
            "recent_runs": [pick(r) for r in sorted(runs(recs), key=lambda r: -r.get("ts", 0))[:8]],
            "slow_tools": [pick(r) for r in tools[:10]], "tools": len(tools),
            "subagents": dict(st([r["secs"] / 60 for r in subs]), top=[pick(r) for r in sorted(subs, key=lambda r: -(r.get("secs") or 0))[:6]]),
            "by_project": by_project}


def _timing(now: float) -> dict:
    try:
        from . import progress
        return timing_summary(progress.records(60), now)
    except Exception:  # timing is optional: never break the dashboard
        return timing_summary([], now)


def _runs(now: float) -> list:
    """Agent runs with live progress on this machine (running, blocked, or finished in the last hour)."""
    try:
        from . import progress
        runs = progress.active_runs()
    except Exception:
        return []
    out = []
    for r in runs:
        if not isinstance(r, dict) or (r.get("state") == "done" and now - (r.get("finished") or 0) > 3600):
            continue
        try:
            b = progress.brief(r)
        except (KeyError, TypeError, ValueError):
            continue
        b.update({"agent": r.get("agent"), "session": r.get("session"), "project": r.get("project"),
                  "estimate_cal": r.get("estimate_cal"), "finished": r.get("finished"),
                  "updates": [{k: u.get(k) for k in ("ts", "kind", "text", "next")} for u in (r.get("updates") or [])[-8:]]})
        out.append(b)
    return out[:20]


OPEN = ("todo", "doing", "blocked")


def kpis(reg: dict, items: list, ppl: list, actions: list, now: float = None) -> dict:
    """The Home summary numbers (work items first; legacy note checkboxes for scopes without items)."""
    now = now or time.time()
    projects = [p for p in reg.get("projects") or [] if isinstance(p, dict)]
    inits = [i for i in reg.get("initiatives") or [] if isinstance(i, dict)]
    scoped = {i["scope"] for i in items}
    open_ = [i for i in items if i["status"] in OPEN]
    doing = len([i for i in open_ if i["status"] == "doing"])
    blocked = len([i for i in open_ if i["status"] == "blocked"])
    n_open = len(open_)
    for scope, t in [(p.get("id"), ((p.get("note_summary") or {}).get("tasks") or {})) for p in projects] + \
            [(f"initiatives/{i.get('id')}", i.get("tasks") or {}) for i in inits]:
        if scope not in scoped and t and t.get("items") is None:
            n_open += int(t.get("open") or 0)
            doing += len(t.get("now") or [])
    failing = sum(1 for p in projects for r in p.get("prs_open") or [] if r.get("checks") == "failing")
    live = sum(len(x["sessions"]) for x in ppl) if ppl else len([s for s in reg.get("sessions") or [] if s.get("active")])
    return {"initiatives": len(inits), "initiatives_active": len([i for i in inits if (i.get("status") or "active") in ("active", "blocked")]),
            "projects": len(projects), "not_cloned": len([p for p in projects if p.get("local") is False]),
            "open": n_open, "doing": doing, "blocked": blocked,
            "people": len(ppl), "people_active": len([x for x in ppl if x["sessions"]]), "live_sessions": live,
            "locks": len([i for i in items if i.get("lock") == "held" and i["status"] in OPEN]),
            "prs_failing": failing, "needs_me": len(actions), "urgent": len([a for a in actions if a["sev"] == "risk"])}


# --------------------------------------------------------------------------- payload

def _canary():
    try:
        from . import canary
        summary = {a: list(v) for a, v in canary.summary(7).items()}
        records = [{k: r.get(k) for k in ("ts", "agent", "project", "ok", "excerpt", "session")}
                   for r in canary.records(30)][-2000:]
        return {"summary": summary, "records": records}
    except Exception:
        return {"summary": {}, "records": []}


def _ops():
    try:
        from . import registry
        return registry.ops_log(80)
    except Exception:
        return []


def _project(p: dict, now: float) -> dict:
    keep = ("id", "owner", "name", "path", "remote", "github", "default_branch", "canonical", "canonical_ok",
            "stack", "commands", "prs_open", "prs_known", "size_kb", "last_activity", "note", "note_summary",
            "activity", "status_line", "plans", "git", "local", "progress", "progress_source", "initiatives")
    out = {k: p.get(k) for k in keep}
    main = p.get("main") or {}
    out["main"] = {k: main.get(k) for k in ("branch", "modified", "untracked", "ahead", "behind", "unpushed",
                                             "ahead_default", "last_commit", "last_commit_ts", "last_activity",
                                             "active", "pr")}
    out["worktrees"] = [{k: w.get(k) for k in WORKTREE_KEYS} for w in p.get("worktrees") or []]
    out["health"] = project_health(p, now)
    ns = p.get("note_summary") or {}
    out["task_index"] = {t: i + 1 for i, t in enumerate(_open_tasks(ns))}
    if isinstance(out.get("status_line"), dict):
        out["status_line"] = dict(out["status_line"], parts=status_parts(out["status_line"].get("line")))
    return out


def _initiative(i: dict, items: list = None) -> dict:
    out = dict(i)
    out["linked_items"] = [x["id"] for x in linked_items(items or [], i.get("id") or "", i.get("projects") or [])]
    out["tasks"] = dict(i.get("tasks") or {})
    out["task_index"] = {t: n + 1 for n, t in enumerate(_open_tasks({"tasks": out["tasks"]}))}
    out["members"] = [dict(m, status_line=dict(m["status_line"], parts=status_parts(m["status_line"].get("line"))))
                      if isinstance(m, dict) and isinstance(m.get("status_line"), dict) else m for m in i.get("members") or []]
    return out


def collect(reg: dict, handoff: Path = None, now: float = None) -> dict:
    now = now or time.time()
    handoff = Path(handoff) if handoff else core.HANDOFF
    files, meta = explorer_files(handoff)
    cache = pr_cache()
    events = guard_events()
    items = read_items(handoff, now)
    team = read_presence(handoff, reg, now=now)
    slog = read_session_log(handoff)
    me = f"{reg.get('github_user') or os.environ.get('USER', '')}@{socket.gethostname().split('.')[0].lower()}"
    ppl = people(team, items, slog, now, local=reg.get("sessions") or [], me=me)
    colls = collisions(ppl, items, now)
    acts = build_actions(reg, now, items, colls)
    for x in ppl:
        x["sessions"] = [_with_status(s) for s in x["sessions"]]
    return {
        "v": 3,
        "version": core.VERSION,
        "copyright": core.COPYRIGHT,
        "generated": int(reg.get("generated") or now),
        "rendered": int(now),
        "host": reg.get("host") or os.uname().nodename.split(".")[0],
        "me": reg.get("github_user") or "",
        "dev_root": core.tilde(reg.get("dev_root") or core.DEV),
        "handoff": core.tilde(handoff),
        "projects": [_project(p, now) for p in reg.get("projects", [])],
        "initiatives": [_initiative(i, items) for i in reg.get("initiatives") or [] if isinstance(i, dict)],
        "actions": acts,
        "kpis": kpis(reg, items, ppl, acts, now),
        "items": items,
        "team": team,
        "people": ppl,
        "session_log": slog,
        "plans": read_plans(handoff),
        "collisions": colls,
        "since": since_yesterday(reg, cache, now, items, slog, me),
        "who": me,
        "timing": _timing(now),
        "runs": _runs(now),
        "merged": merged_prs(cache, now - 30 * 86400)[:200],
        "sessions": [_with_status(s) for s in reg.get("sessions") or []],
        "providers": reg.get("providers") or {},
        "issues": [{"kind": i[0], "text": i[1]} if isinstance(i, (list, tuple)) else {"kind": "info", "text": str(i)}
                   for i in reg.get("issues") or []],
        "canary": _canary(),
        "ops": _ops(),
        "guard": events[-120:],
        "guard_rules": guard_rules(events),
        "drift": reg.get("drift"),
        "files": files,
        "files_meta": meta,
    }

